var doc = app.activeDocument;
var bg = doc.backgroundLayer;
bg.isBackgroundLayer = false;   // Layer from Background
bg.name = "photo";

// Clear all effects via Action Manager
var ref = new ActionReference();
ref.putEnumerated(stringIDToTypeID("layer"), stringIDToTypeID("ordinal"), stringIDToTypeID("targetEnum"));
var d = new ActionDescriptor();
d.putReference(stringIDToTypeID("null"), ref);
executeAction(stringIDToTypeID("disableLayerStyle"), d, DialogModes.NO);
